/** Per-language notes for languages that are not in the full COURSE table.
 * Card lines are the ones already on the A1 deck. Later steps add the real marker
 * for past, comparison, if, and concession, checked against that language’s grammar.
 */
type Pair = { body: string; pattern: string };
type Steps = Record<string, Pair>;

function n(body: string, pattern: string): Pair {
  return { body, pattern };
}

